{
  "tools": [
    {
      "description": "Receive a bounded batch of reports for your CURRENT active turn and record receipt so they do not replay as another turn. Takes no session ID. When coordinating children, call before delegation/integration decisions, after long validation, and before final synthesis. Read the whole batch before acting. A boundary means yield at a safe point for normal queue delivery. Do not poll an empty inbox; end the turn when no independent work remains. Supports Claude Code, Codex and Cursor MCP turns with verifiable tool-call identity.",
      "inputSchema": {
        "properties": {
          "checkpointId": {
            "description": "Unique name for this checkpoint (letters, digits, underscores or hyphens; max 100). Reuse only when retrying this same read; use a new name for a later checkpoint.",
            "type": "string"
          },
          "nimbalyst_session_id": {
            "description": "Required exact current Nimbalyst session ID; copy the ID supplied in the current Nimbalyst prompt. The bridge validates that it belongs to this workspace.",
            "type": "string"
          }
        },
        "required": [
          "checkpointId",
          "nimbalyst_session_id"
        ],
        "type": "object"
      },
      "server": "nimbalyst",
      "serverName": "nimbalyst",
      "serverStatus": "connected",
      "toolName": "consume_session_inbox"
    }
  ]
}
